cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and simplest cases ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a single plain sword for a 0-year customer as 115 G (100 base + 10 first insurance + 5 fee)");

  // --- Price list: every main item type has its own base premium ---
  it.todo("quotes a plain amulet for a 0-year customer as 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quotes a plain staff for a 0-year customer as 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quotes a plain potion for a 0-year customer as 49 G (40 base + 4 first insurance + 5 fee)");

  // --- Components: base premium 25 G each ---
  it.todo("quotes 1 rune as a 25 G base premium");
  it.todo("quotes 1 moonstone as a 25 G base premium");
  it.todo("quotes 2 runes as a 50 G base premium (no block)");
  it.todo("quotes 3 runes as a 60 G base premium (block applies)");
  it.todo("quotes 4 runes as a 100 G base premium (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as a 175 G base premium (no block -- 7 is not exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone as a 75 G base premium (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones as a 120 G base premium (two separate blocks)");

  // --- Item modifiers ---
  it.todo("adds a 50% curse surcharge to the cursed item's base premium (cursed sword base contribution 150 G)");
  it.todo("adds a 30% high-enchantment surcharge at enchantment exactly 5 (sword base contribution 130 G)");
  it.todo("adds no high-enchantment surcharge at enchantment 4");
  it.todo("adds both curse and high-enchantment surcharges to a cursed sword with enchantment 5 (180 G contribution)");
  it.todo("applies the curse surcharge only to the cursed item on a multi-item policy -- cursed sword + plain amulet = 210 G before policy modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20% loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 10% first-insurance surcharge on the policy base premium");
  it.todo("applies a 15% follow-up discount on every contract after the first quote in a scenario");
  it.todo("applies no follow-up discount to the first quote in a scenario");
  it.todo("still applies the first-insurance surcharge on a follow-up contract (each quote is a first insurance for its items)");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) as 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as 160 G");

  // --- Insurance sum and cap ---
  it.todo("reports an insurance sum of 1600 G and cap 3200 G for a policy of a sword and an amulet");
  it.todo("reports an insurance sum of 2000 G and cap 4000 G for a policy of two swords");
  it.todo("reports an insurance sum of 1750 G and cap 3500 G for a sword plus a 3-rune block (block discount affects premium only)");
  it.todo("bases the cap on the unmodified insurance value -- cursed sword premium 165 G, cap still 2000 G");

  // --- Claims: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a regular steel sword (enchantment 3) with 500 G damage (500 - 100 deductible)");
  it.todo("pays out 100 G for a damaged rune with 200 G damage (runes have no enchantment or material)");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G = 600 G payout");

  // --- Claims: special clauses ---
  it.todo("reimburses 50% for enchantment exactly 8 -- dragon sword, 1000 G damage, payout 400 G");
  it.todo("applies only the high-enchantment clause for a steel sword at enchantment 9 -- 1000 G damage, payout 400 G");
  it.todo("applies only the dragon-material clause at enchantment 5 -- dragon sword, 800 G damage, payout 700 G");
  it.todo("lets the 50% rule win when both clauses apply -- dragon sword, enchantment 9, 1000 G damage, payout 400 G");
  it.todo("applies no special clause below enchantment 8 for non-dragon material");

  // --- Claims: multiple items of the same type ---
  it.todo("treats two sword damage entries on a two-sword policy as separate damages, each with its own deductible");

  // --- Claims: cap exhaustion across successive claims ---
  it.todo("reports remainingCap after a claim -- sword policy cap 2000 G, first claim of 1500 G pays 1400 G leaving 600 G");
  it.todo("reduces a later payout to the remaining cap -- second claim of 1500 G pays only 600 G leaving 0 G");

  // --- Claims: rounding in the MHPCO's favor ---
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favor)");

  // --- Error cases (observable contract: the domain layer throws an Error;
  //     the CLI translates that into a non-zero exit and a stderr description) ---
  it.todo("throws an Error when a quote contains an unknown item type such as broomstick");
  it.todo("throws an Error when a claim damages an item type not covered by the policy (amulet damaged, only a sword insured)");
  it.todo("throws an Error when a claim damages an unknown item type");
  it.todo("throws an Error when a claim has more damage entries of a type than the policy covers (two sword damages, one sword insured)");
  it.todo("throws an Error when a claim damage amount is negative (-200)");

  // --- CLI adapter ---
  it.todo("CLI reads the schema example from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout with exit code 0");
  it.todo("CLI exits non-zero and writes an error description to stderr for an unknown item type, writing no results to stdout");
  it.todo("CLI exits non-zero and writes an error description to stderr for a negative damage amount");
  it.todo("CLI processes steps sequentially so a claim can reference an earlier quote's policy by step index");
});
EOF
