export function runScenario(scenario: Scenario): ScenarioResults {
  const results: (QuoteResult | ClaimResult)[] = [];
  const policies = new Map<number, Policy>();
  let contracts = 0;

  scenario.steps.forEach((step, index) => {
    if (step.op === "quote") {
      step.items.forEach((item) => requireInsurableType(item.type));
      results.push({ premium: quotePremium(step.items, scenario.customer, contracts) });
      contracts += 1;
      policies.set(index, issuePolicy(step.items));
      return;
    }
    const policy = policies.get(step.policy) as Policy;
    results.push(settleClaim(policy, step.incident.damages));
  });

  return { results };
}

